"""Migration of Meridian CRM 4.2 order validation rules ORD-001 through ORD-005."""

from decimal import Decimal, InvalidOperation


def _value(row: dict | None, column: str) -> object:
    """Return a field value, treating a missing row or field as the legacy empty string."""
    if row is None:
        return ""
    return row.get(column, "")


def _numeric(value: object) -> Decimal:
    """Apply legacy numeric coercion: an empty value compares as zero."""
    if value == "":
        return Decimal("0")
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal("0")


def _lookup(
    tables: dict | None,
    table_name: str,
    key_column: str,
    key_value: object,
    output_column: str,
) -> object:
    """Implement legacy LOOKUP, including live-row visibility and source iteration order."""
    if tables is None:
        return ""

    rows = tables.get(table_name, [])
    for row in rows:
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_column, "") == key_value:
            return row.get(output_column, "")
    return ""


def _error(code: str, message: str) -> dict:
    return {"code": code, "message": message, "severity": "BLOCK"}


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Validate an order header or order line using migrated legacy VRL rules."""
    errors: list[dict] = []

    if table == "ORD_HEADER":
        # ORD-001: INSERT, UPDATE
        if event in ("INSERT", "UPDATE"):
            disc_pct = _numeric(_value(record, "DISC_PCT"))
            if not (disc_pct >= Decimal("0") and disc_pct <= Decimal("100")):
                errors.append(_error("E5001", "Discount out of range"))

        # ORD-002: UPDATE
        if event == "UPDATE":
            disc_pct = _numeric(_value(record, "DISC_PCT"))
            owner_uid = _value(record, "OWNER_UID")
            role_id = _lookup(
                tables, "USR_MASTER", "USR_ID", owner_uid, "ROLE_ID"
            )
            if disc_pct > Decimal("20") and role_id != "MGR" and role_id != "ADMIN":
                errors.append(
                    _error(
                        "E5002",
                        "Discount over 20 percent requires manager role",
                    )
                )

        # ORD-003: UPDATE
        if event == "UPDATE":
            if (
                _value(old, "STAT_CD") == "I"
                and _value(record, "STAT_CD") != "I"
                and _value(record, "STAT_CD") != "X"
            ):
                errors.append(
                    _error("E5003", "Invoiced order can only be cancelled")
                )

    elif table == "ORD_LINE":
        # ORD-004: INSERT, UPDATE
        if event in ("INSERT", "UPDATE"):
            if not (_numeric(_value(record, "QTY")) > Decimal("0")):
                errors.append(_error("E5004", "Quantity must be positive"))

        # ORD-005: INSERT
        if event == "INSERT":
            product_id = _value(record, "PROD_ID")
            active_flag = _lookup(
                tables, "PROD_MASTER", "PROD_ID", product_id, "ACTIVE_FLG"
            )
            if active_flag != "Y":
                errors.append(_error("E5005", "Product not active"))

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure is blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
